CREATE TYPE "DataClassification" AS ENUM ('PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'SENSITIVE', 'RESTRICTED');
CREATE TYPE "PositionStatus" AS ENUM ('OCCUPIED', 'VACANT', 'FROZEN', 'PLANNED', 'CLOSED');
CREATE TYPE "EmployeeStatus" AS ENUM ('ACTIVE', 'ON_LEAVE', 'TERMINATED', 'SUSPENDED', 'PRE_HIRE');
CREATE TYPE "EmploymentType" AS ENUM ('EMPLOYEE', 'CONTRACTOR', 'INTERN', 'APPRENTICE', 'TEMPORARY');
CREATE TYPE "PeopleRole" AS ENUM ('SUPER_ADMIN', 'PEOPLE_ADMIN', 'HR_MANAGER', 'HR_ANALYST', 'RECRUITER', 'PAYROLL_MANAGER', 'PAYROLL_ANALYST', 'TIME_MANAGER', 'BENEFITS_ANALYST', 'MANAGER', 'EMPLOYEE', 'AUDITOR', 'DPO');
CREATE TYPE "AccessScopeType" AS ENUM ('COMPANY', 'LEGAL_ENTITY', 'BRANCH', 'UNIT', 'DEPARTMENT', 'COST_CENTER', 'TEAM', 'SUBORDINATES', 'SELF');
CREATE TYPE "SensitiveFieldKey" AS ENUM ('SALARY', 'BANK_ACCOUNTS', 'DOCUMENTS', 'DEPENDENTS', 'MEDICAL_INFORMATION', 'BIOMETRICS', 'CONFIDENTIAL_EVALUATIONS', 'DISCIPLINARY_MEASURES');

CREATE TABLE "BusinessGroup" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "BusinessGroup_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Company" ("id" TEXT NOT NULL, "businessGroupId" TEXT, "name" TEXT NOT NULL, "legalName" TEXT NOT NULL, "registrationNumber" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Company_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LegalEntity" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "name" TEXT NOT NULL, "registrationNumber" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "LegalEntity_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Branch" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Branch_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Establishment" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Establishment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Department" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Department_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CostCenter" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CostCenter_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Team" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Team_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Job" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "title" TEXT NOT NULL, "code" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Job_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Position" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "departmentId" TEXT NOT NULL, "jobId" TEXT, "title" TEXT NOT NULL, "status" "PositionStatus" NOT NULL DEFAULT 'VACANT', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Position_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SalaryBand" ("id" TEXT NOT NULL, "jobId" TEXT NOT NULL, "name" TEXT NOT NULL, "minimumAmount" DECIMAL(14,2) NOT NULL, "midpointAmount" DECIMAL(14,2) NOT NULL, "maximumAmount" DECIMAL(14,2) NOT NULL, "currency" TEXT NOT NULL DEFAULT 'BRL', "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SalaryBand_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WorkLocation" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "address" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WorkLocation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Person" ("id" TEXT NOT NULL, "fullName" TEXT NOT NULL, "preferredName" TEXT, "corporateEmail" TEXT NOT NULL, "personalEmail" TEXT, "phone" TEXT, "dataClassification" "DataClassification" NOT NULL DEFAULT 'CONFIDENTIAL', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Person_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Employee" ("id" TEXT NOT NULL, "personId" TEXT NOT NULL, "companyId" TEXT NOT NULL, "positionId" TEXT, "employeeNumber" TEXT NOT NULL, "status" "EmployeeStatus" NOT NULL DEFAULT 'ACTIVE', "hireDate" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Employee_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EmployeeProfile" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "bio" TEXT, "dataClassification" "DataClassification" NOT NULL DEFAULT 'CONFIDENTIAL', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "EmployeeProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Employment" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "type" "EmploymentType" NOT NULL, "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "recordedBy" TEXT NOT NULL, "reason" TEXT NOT NULL, "source" TEXT NOT NULL, CONSTRAINT "Employment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EmploymentContract" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "contractNumber" TEXT NOT NULL, "type" "EmploymentType" NOT NULL, "dataClassification" "DataClassification" NOT NULL DEFAULT 'RESTRICTED', "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "recordedBy" TEXT NOT NULL, "reason" TEXT NOT NULL, "source" TEXT NOT NULL, CONSTRAINT "EmploymentContract_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EmploymentHistory" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "eventType" TEXT NOT NULL, "description" TEXT NOT NULL, "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "recordedBy" TEXT NOT NULL, "reason" TEXT NOT NULL, "source" TEXT NOT NULL, CONSTRAINT "EmploymentHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PositionAssignment" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "positionId" TEXT NOT NULL, "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "recordedBy" TEXT NOT NULL, "reason" TEXT NOT NULL, "source" TEXT NOT NULL, CONSTRAINT "PositionAssignment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DepartmentAssignment" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "departmentId" TEXT NOT NULL, "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "recordedBy" TEXT NOT NULL, "reason" TEXT NOT NULL, "source" TEXT NOT NULL, CONSTRAINT "DepartmentAssignment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ManagerAssignment" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "managerId" TEXT NOT NULL, "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "recordedBy" TEXT NOT NULL, "reason" TEXT NOT NULL, "source" TEXT NOT NULL, CONSTRAINT "ManagerAssignment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CostCenterAssignment" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "costCenterId" TEXT NOT NULL, "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "recordedBy" TEXT NOT NULL, "reason" TEXT NOT NULL, "source" TEXT NOT NULL, CONSTRAINT "CostCenterAssignment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CompensationHistory" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "baseSalary" DECIMAL(14,2) NOT NULL, "currency" TEXT NOT NULL DEFAULT 'BRL', "dataClassification" "DataClassification" NOT NULL DEFAULT 'RESTRICTED', "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "recordedBy" TEXT NOT NULL, "reason" TEXT NOT NULL, "source" TEXT NOT NULL, CONSTRAINT "CompensationHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EmployeeAddress" ("id" TEXT NOT NULL, "personId" TEXT NOT NULL, "addressLine" TEXT NOT NULL, "city" TEXT NOT NULL, "state" TEXT NOT NULL, "postalCode" TEXT NOT NULL, "country" TEXT NOT NULL DEFAULT 'BR', "dataClassification" "DataClassification" NOT NULL DEFAULT 'CONFIDENTIAL', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "EmployeeAddress_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EmergencyContact" ("id" TEXT NOT NULL, "personId" TEXT NOT NULL, "name" TEXT NOT NULL, "relationship" TEXT NOT NULL, "phone" TEXT NOT NULL, "dataClassification" "DataClassification" NOT NULL DEFAULT 'CONFIDENTIAL', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "EmergencyContact_pkey" PRIMARY KEY ("id"));
