CREATE TABLE "EmployeeStatusHistory" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "status" "EmployeeStatus" NOT NULL, "effectiveFrom" TIMESTAMP(3) NOT NULL, "effectiveTo" TIMESTAMP(3), "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "recordedBy" TEXT NOT NULL, "reason" TEXT NOT NULL, "source" TEXT NOT NULL, CONSTRAINT "EmployeeStatusHistory_pkey" PRIMARY KEY ("id"));
