CREATE TABLE "AccessScope" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "companyId" TEXT, "type" "AccessScopeType" NOT NULL, "scopeId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AccessScope_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FieldPermission" ("id" TEXT NOT NULL, "employeeId" TEXT NOT NULL, "fieldKey" "SensitiveFieldKey" NOT NULL, "canRead" BOOLEAN NOT NULL DEFAULT false, "canWrite" BOOLEAN NOT NULL DEFAULT false, "grantedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "grantedBy" TEXT NOT NULL, CONSTRAINT "FieldPermission_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL, "actorId" TEXT, "actorRole" TEXT NOT NULL, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT NOT NULL, "before" JSONB, "after" JSONB, "reason" TEXT, "requestId" TEXT, "correlationId" TEXT, "ip" TEXT, "userAgent" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DataAccessLog" ("id" TEXT NOT NULL, "employeeId" TEXT, "actorId" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT NOT NULL, "fieldKey" TEXT NOT NULL, "purpose" TEXT NOT NULL, "requestId" TEXT, "correlationId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DataAccessLog_pkey" PRIMARY KEY ("id"));

